import {
  Api2
} from "./request-tracing-4nbah0zs.js";

// src/handlers/config.ts
import { Config } from "@opencode/core/config";
import { ShellSelect } from "@opencode/core/shell/select";
import { Effect } from "effect";
import { HttpApiBuilder } from "effect/http-api";
var ConfigHandler2 = HttpApiBuilder.group(Api2, "server.config", (handlers) => handlers.handle("config.get", () => Config.Service.use((config) => config.entries())).handle("config.update", Effect.fn(function* (ctx) {
  const config = yield* Config.Service;
  if (!config.update)
    return yield* Effect.die(new Error("Config updates are unavailable"));
  return yield* config.update(ctx.payload).pipe(Effect.orDie);
})).handle("config.shells", Effect.fn(function* () {
  const shell = yield* ShellSelect.Service;
  if (!shell.list)
    return yield* Effect.die(new Error("Shell discovery is unavailable"));
  return yield* shell.list();
})));

export { ConfigHandler2 };
